assert len(speaker_notes) == 15, f"Expected 15 speaker notes, got {len(speaker_notes)}"
assert len(archive_details) == 15, f"Expected 15 archive details, got {len(archive_details)}"

slides_js_path = DECK / "slides.js"
with open(slides_js_path, "r", encoding="utf-8") as f:
    orig = f.read()

head_idx = orig.find("const SPEAKER_NOTES = [")
tail_idx = orig.find("function fitStage()")

new_notes_js = "const SPEAKER_NOTES = " + json.dumps(speaker_notes, ensure_ascii=False, indent=2) + ";\n\n"
new_slides_js = orig[:head_idx] + new_notes_js + orig[tail_idx:]

with open(slides_js_path, "w", encoding="utf-8") as f:
    f.write(new_slides_js)
print(f"Updated {slides_js_path} with 15 speaker notes.")

archive_js_path = DECK / "archive_details.js"
new_archive_js = "window.ARCHIVE_DETAILS = " + json.dumps(archive_details, ensure_ascii=False, indent=2) + ";\n"
with open(archive_js_path, "w", encoding="utf-8") as f:
    f.write(new_archive_js)
print(f"Updated {archive_js_path} with 15 archive details.")
